88	    public OwnerRestControllerV1(ClinicService clinicService,
89	                                 OwnerMapper ownerMapper,
90	                                 PetMapper petMapper,
91	                                 VisitMapper visitMapper,
92	                                 TelephoneNormalizer telephoneNormalizer,
93	                                 AddressNormalizer addressNormalizer,
94	                                 EmailNormalizer emailNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.telephoneNormalizer = telephoneNormalizer;
100	        this.addressNormalizer = addressNormalizer;
101	        this.emailNormalizer = emailNormalizer;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
127	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
128	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
134	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
135	        rejectBlankOwnerFields(ownerFieldsDto);
136	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
137	        if (!sharesHousehold) {
138	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
139	        }
140	        rejectCityAtCapacity(ownerFieldsDto.getCity());
141	        LocalDate registrationDate = businessDay(effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate()));
142	        rejectDailyRegistrationLimit(registrationDate);
143	        String normalizedTelephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
144	        rejectDuplicateTelephone(normalizedTelephone);
145	        ownerFieldsDto.setTelephone(normalizedTelephone);
146	        String normalizedEmail = emailNormalizer.normalize(ownerFieldsDto.getEmail());
147	        rejectDuplicateEmail(normalizedEmail);
148	        ownerFieldsDto.setEmail(normalizedEmail);
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        owner.setRegistrationDate(registrationDate);
152	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
153	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
154	        if (sharesHousehold) {
155	            owner.setHouseholdId(householdId(owner.getLastName(), owner.getAddress()));
156	        }
157	        this.clinicService.saveOwner(owner);
158	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
159	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
160	            ownerMapper.membershipLevel(owner));
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
171	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
172	        if (currentOwner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        currentOwner.setAddress(ownerFieldsDto.getAddress());
176	        currentOwner.setCity(ownerFieldsDto.getCity());
177	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
178	        currentOwner.setLastName(ownerFieldsDto.getLastName());
179	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
180	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
181	        this.clinicService.saveOwner(currentOwner);
182	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
183	    }
