234	    @Override
235	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
236	        HttpHeaders headers = new HttpHeaders();
237	        Visit visit = visitMapper.toVisit(visitFieldsDto);
238	        Pet pet = new Pet();
239	        pet.setId(petId);
240	        visit.setPet(pet);
241	        this.clinicService.saveVisit(visit);
242	        VisitDto visitDto = visitMapper.toVisitDto(visit);
243	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
