249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner != null) {
254	            Pet pet = owner.getPet(petId);
255	            if (pet != null) {
256	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	
262	    /**
263	     * Rejects an owner whose required text fields are blank (whitespace-only). Missing (null)
264	     * and empty fields are already rejected by Bean Validation on {@link OwnerFieldsDto}; this
265	     * closes the gap for {@code address} and {@code city}, whose values may be non-empty yet
266	     * blank (e.g. {@code "   "}). The offending field names are reported through an
267	     * {@link InvalidOwnerFieldsException}, which the {@code ExceptionControllerAdvice} renders
268	     * as a 400 response carrying an {@code errors} array of field names.
269	     *
270	     * @param ownerFieldsDto the submitted owner fields
271	     * @throws InvalidOwnerFieldsException if one or more required fields are blank
272	     */
273	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
274	        List<String> blankFields = new ArrayList<>();
275	        addIfBlank(blankFields, "firstName", ownerFieldsDto.getFirstName());
276	        addIfBlank(blankFields, "lastName", ownerFieldsDto.getLastName());
277	        addIfBlank(blankFields, "address", ownerFieldsDto.getAddress());
278	        addIfBlank(blankFields, "city", ownerFieldsDto.getCity());
279	        addIfBlank(blankFields, "telephone", ownerFieldsDto.getTelephone());
280	        if (!blankFields.isEmpty()) {
281	            throw new InvalidOwnerFieldsException(blankFields);
282	        }
283	    }
284	
285	    private void addIfBlank(List<String> blankFields, String field, String value) {
286	        if (value != null && value.isBlank()) {
287	            blankFields.add(field);
288	        }
289	    }
290	
291	    /**
292	     * Builds the {@code customerCode} assigned to a newly created owner, formatted
293	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
294	     * owner's {@code city}, {@code LAST3} is the upper-cased first three letters of the owner's
295	     * {@code lastName}, and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one
296	     * more than the number of owners already in that city (e.g. {@code 'MEL-SMI-0007'}).
297	     *
298	     * @param city the city of the owner being created
299	     * @param lastName the last name of the owner being created
300	     * @return the formatted customer code
301	     */
302	    private String nextCustomerCode(String city, String lastName) {
303	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
304	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
305	        long sequence = this.clinicService.findAllOwners().stream()
306	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
307	            .count() + 1L;
308	        return String.format("%s-%s-%04d", city3, last3, sequence);
309	    }
310	
311	    /**
312	     * Counts how many existing owners already share the given {@code firstName} and {@code lastName},
313	     * compared case-insensitively (using {@link java.util.Locale#ROOT}-independent
314	     * {@link String#equalsIgnoreCase(String)}). The count reflects the owners present before the
315	     * current create, so a name that is unique on create yields {@code 0}. The value is stored on the
316	     * new owner and surfaced as the read-only {@code namesakeCount} field.
317	     *
318	     * @param firstName the first name of the owner being created
319	     * @param lastName the last name of the owner being created
320	     * @return the number of existing owners with the same first and last name (case-insensitive)
321	     */
322	    private int namesakeCount(String firstName, String lastName) {
323	        return (int) this.clinicService.findAllOwners().stream()
324	            .filter(owner -> equalsIgnoreCase(owner.getFirstName(), firstName)
325	                && equalsIgnoreCase(owner.getLastName(), lastName))
326	            .count();
327	    }
328	
329	    private boolean equalsIgnoreCase(String a, String b) {
330	        return a == null ? b == null : a.equalsIgnoreCase(b);
331	    }
332	
333	    /**
334	     * The maximum number of owners a single city may contain. Once a city already holds this many
335	     * owners, further owners in that city are rejected by {@link #rejectCityAtCapacity(String)}.
336	     */
337	    private static final long MAX_OWNERS_PER_CITY = 50L;
338	
339	    /**
340	     * Rejects a create request whose city already contains {@link #MAX_OWNERS_PER_CITY} or more
341	     * owners. Existing owners are matched to the requested city case-insensitively (using
342	     * {@link java.util.Locale#ROOT}-independent {@link String#equalsIgnoreCase(String)}), mirroring
343	     * the per-city counting used for the customer code. A city at capacity is reported through an
344	     * {@link OwnerCityAtCapacityException}, which the {@code ExceptionControllerAdvice} renders as a
345	     * 409 Conflict response.
346	     *
347	     * @param city the city of the owner being created
348	     * @throws OwnerCityAtCapacityException if the city already holds the maximum number of owners
349	     */
350	    private void rejectCityAtCapacity(String city) {
351	        long owners = this.clinicService.findAllOwners().stream()
352	            .filter(owner -> equalsIgnoreCase(owner.getCity(), city))
353	            .count();
354	        if (owners >= MAX_OWNERS_PER_CITY) {
355	            throw new OwnerCityAtCapacityException(city);
356	        }
357	    }
358	
359	    /**
360	     * The maximum number of owners that may be registered on a single day. Once this many owners
361	     * already carry a given {@code registrationDate}, further owners for that date are rejected by
362	     * {@link #rejectDailyRegistrationLimit(LocalDate)}.
363	     */
364	    private static final long MAX_OWNERS_PER_DAY = 100L;
365	
366	    /**
367	     * Resolves the effective registration date for a create request: the value supplied in the
368	     * request when present, otherwise the server's current date. The result is the raw effective
369	     * date before the business-day adjustment applied by {@link #businessDay(LocalDate)}.
370	     *
371	     * @param suppliedDate the registration date from the request, or {@code null} when omitted
372	     * @return the supplied date, or today when none was supplied
373	     */
374	    private LocalDate effectiveRegistrationDate(LocalDate suppliedDate) {
375	        return suppliedDate != null ? suppliedDate : LocalDate.now();
376	    }
377	
378	    /**
379	     * Adjusts a date so it falls on a business day. A Saturday is rolled forward to the following
380	     * Monday and a Sunday to the next day (Monday); any weekday is returned unchanged. Applied to
381	     * the effective registration date so that a weekend value - whether supplied in the request or
382	     * defaulted to the server date - is stored as the next Monday, and every value derived from the
383	     * registration date (such as the membership number's year segment and the daily create-limit
384	     * bucket) uses the adjusted business day.
385	     *
386	     * @param date the effective registration date
387	     * @return the same date when it is a weekday, otherwise the next Monday
388	     */
389	    private LocalDate businessDay(LocalDate date) {
390	        DayOfWeek dayOfWeek = date.getDayOfWeek();
391	        if (dayOfWeek == DayOfWeek.SATURDAY) {
392	            return date.plusDays(2);
393	        }
394	        if (dayOfWeek == DayOfWeek.SUNDAY) {
395	            return date.plusDays(1);
396	        }
397	        return date;
398	    }
399	
400	    /**
401	     * Rejects a create request once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
402	     * created on the given day, counted by {@code registrationDate}. A day at capacity is reported
403	     * through a {@link DailyOwnerRegistrationLimitException}, which the {@code ExceptionControllerAdvice}
404	     * renders as a 429 Too Many Requests response.
405	     *
406	     * @param date the registration date of the owner being created (today)
407	     * @throws DailyOwnerRegistrationLimitException if the day already holds the maximum number of owners
408	     */
409	    private void rejectDailyRegistrationLimit(LocalDate date) {
410	        long owners = this.clinicService.findAllOwners().stream()
411	            .filter(owner -> date.equals(owner.getRegistrationDate()))
412	            .count();
413	        if (owners >= MAX_OWNERS_PER_DAY) {
414	            throw new DailyOwnerRegistrationLimitException(date);
415	        }
416	    }
417	
418	    /**
419	     * The soft daily create threshold above which the read-only {@code bulkSignupWarning} flag is
420	     * raised. Once more than this many owners share a {@code registrationDate}, that day is flagged
421	     * as unusually high volume - a warning well below the hard {@link #MAX_OWNERS_PER_DAY} cap.
422	     */
423	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
424	
425	    /**
426	     * Derives the read-only {@code bulkSignupWarning} flag for an owner: {@code true} when more than
427	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have been created (counted by
428	     * {@code registrationDate}) on the given day, otherwise {@code false}. Uses the same per-day
429	     * accumulation as {@link #rejectDailyRegistrationLimit(LocalDate)}. A {@code null} date (an owner
430	     * without a registration date, such as seed data) is never flagged.
431	     *
432	     * @param date the owner's registration date (the day it was created), or {@code null}
433	     * @return {@code true} if the day already holds more than the warning threshold of owners
434	     */
435	    private boolean bulkSignupWarning(LocalDate date) {
436	        if (date == null) {
437	            return false;
438	        }
439	        long owners = this.clinicService.findAllOwners().stream()
440	            .filter(owner -> date.equals(owner.getRegistrationDate()))
441	            .count();
442	        return owners > BULK_SIGNUP_WARNING_THRESHOLD;
443	    }
444	
445	    /**
446	     * Rejects a create request whose normalized telephone is already used by any existing owner.
447	     * Existing owners' telephones are reduced to the same canonical form (via
448	     * {@link TelephoneNormalizer#canonicalize(String)}) before comparison, so numbers that differ
449	     * only in formatting still collide. A collision is reported through a
450	     * {@link DuplicateOwnerTelephoneException}, which the {@code ExceptionControllerAdvice} renders
451	     * as a 409 Conflict response.
452	     *
453	     * @param normalizedTelephone the canonical telephone of the owner being created
454	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
455	     */
456	    private void rejectDuplicateTelephone(String normalizedTelephone) {
457	        boolean duplicate = existingOwnerMatches(
458	            owner -> owner.getTelephone() == null ? null : telephoneNormalizer.canonicalize(owner.getTelephone()),
459	            normalizedTelephone);
460	        if (duplicate) {
461	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
462	        }
463	    }
464	
465	    /**
466	     * Rejects a create request whose normalized (lower-cased) email is already used by any existing
467	     * owner. Existing owners' emails are reduced to the same canonical form (via
468	     * {@link EmailNormalizer#normalize(String)}, i.e. lower-cased) before comparison, so addresses
469	     * that differ only in casing still collide. Owners without an email are ignored, and a request
470	     * without an email is never rejected. A collision is reported through a
471	     * {@link DuplicateOwnerEmailException}, which the {@code ExceptionControllerAdvice} renders as a
472	     * 409 Conflict response.
473	     *
474	     * @param normalizedEmail the canonical (lower-cased) email of the owner being created, or
475	     * {@code null} when none was supplied
476	     * @throws DuplicateOwnerEmailException if another owner already uses this email
477	     */
478	    private void rejectDuplicateEmail(String normalizedEmail) {
479	        if (normalizedEmail == null) {
480	            return;
481	        }
482	        boolean duplicate = existingOwnerMatches(
483	            owner -> emailNormalizer.normalize(owner.getEmail()),
484	            normalizedEmail);
485	        if (duplicate) {
486	            throw new DuplicateOwnerEmailException(normalizedEmail);
487	        }
488	    }
489	
490	    /**
491	     * Reports whether any existing owner already carries the given comparison {@code key}, derived
492	     * from each owner by {@code keyExtractor}. Owners for which the extractor yields {@code null}
493	     * are ignored. The create endpoint's duplicate checks use this to reduce both an existing owner
494	     * and the owner being created to the same canonical key and reject a match.
495	     *
496	     * @param keyExtractor derives an owner's canonical comparison key (may return {@code null})
497	     * @param key the canonical key of the owner being created
498	     * @return {@code true} if some existing owner shares the key
499	     */
500	    private boolean existingOwnerMatches(Function<Owner, String> keyExtractor, String key) {
501	        return this.clinicService.findAllOwners().stream()
502	            .map(keyExtractor)
503	            .filter(Objects::nonNull)
504	            .anyMatch(key::equals);
505	    }
506	
507	    /**
508	     * Rejects a create request that shares a household with an existing owner: another owner already
509	     * has the same {@code lastName} and the same {@code address}. Both values are compared in
510	     * canonical form (case-insensitive with surrounding and internal whitespace collapsed to a single
511	     * space, see {@link #canonicalizeHousehold(String)}), so values that differ only in casing or
512	     * spacing still collide. A collision is reported through a {@link DuplicateOwnerHouseholdException},
513	     * which the {@code ExceptionControllerAdvice} renders as a 409 Conflict response. Callers skip this
514	     * check when the request opts in via {@code sharesHousehold}.
515	     *
516	     * @param lastName the last name of the owner being created
517	     * @param address the address of the owner being created
518	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household
519	     */
520	    private void rejectDuplicateHousehold(String lastName, String address) {
521	        String canonicalLastName = canonicalizeHousehold(lastName);
522	        String canonicalAddress = canonicalizeHousehold(address);
523	        if (canonicalLastName == null || canonicalAddress == null) {
524	            return;
525	        }
526	        boolean duplicate = this.clinicService.findAllOwners().stream()
527	            .anyMatch(owner -> canonicalLastName.equals(canonicalizeHousehold(owner.getLastName()))
528	                && canonicalAddress.equals(canonicalizeHousehold(owner.getAddress())));
529	        if (duplicate) {
530	            throw new DuplicateOwnerHouseholdException(canonicalLastName, canonicalAddress);
531	        }
532	    }
533	
534	    /**
535	     * Reduces a household field ({@code lastName} or {@code address}) to a canonical form for
536	     * case-insensitive, whitespace-insensitive comparison: leading and trailing whitespace is
537	     * trimmed, every run of internal whitespace is collapsed to a single space, and the result is
538	     * lower-cased using {@link java.util.Locale#ROOT} so comparison is locale-independent.
539	     *
540	     * @param value the raw field value, or {@code null}
541	     * @return the canonical value, or {@code null} when {@code value} is {@code null}
542	     */
543	    private String canonicalizeHousehold(String value) {
544	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
545	    }
546	
547	    /**
548	     * Derives the stable, shared {@code householdId} for an owner joining a household via
549	     * {@code sharesHousehold}. The identifier is a deterministic function of the canonical
550	     * {@code lastName} and {@code address} (see {@link #canonicalizeHousehold(String)}), so every
551	     * owner with the same last name at the same address - regardless of casing or spacing - is
552	     * assigned the identical value. It is the first 16 upper-case hex characters of the SHA-256 hash
553	     * of the two canonical fields joined by a delimiter that cannot occur in the input.
554	     *
555	     * @param lastName the last name of the owner being created
556	     * @param address the address of the owner being created
557	     * @return the shared household identifier
558	     */
559	    private String householdId(String lastName, String address) {
560	        String key = canonicalizeHousehold(lastName) + "\n" + canonicalizeHousehold(address);
561	        try {
562	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
563	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
564	            StringBuilder sb = new StringBuilder(digest.length * 2);
565	            for (byte b : digest) {
566	                sb.append(String.format("%02X", b));
567	            }
568	            return sb.substring(0, 16);
569	        } catch (java.security.NoSuchAlgorithmException e) {
570	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
571	        }
572	    }
573	}
