17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	    private static final String ERROR_DUPLICATE_TELEPHONE = "The telephone number is already used by another owner";
57	    private static final String ERROR_DUPLICATE_EMAIL = "The email address is already used by another owner";
58	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the same last name and address already exists";
59	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
60	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
61	
62	    /**
63	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
64	     * class.
65	     *
66	     * @param e     Object referring to the thrown exception.
67	     * @param status HTTP response status.
68	     * @param url URL request.
69	     */
70	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
71	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
72	        problemDetail.setType(URI.create(url.toString()));
73	        problemDetail.setTitle(e.getClass().getSimpleName());
74	        problemDetail.setDetail(detail);
75	        problemDetail.setProperty("timestamp", Instant.now());
76	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
77	        return problemDetail;
78	    }
79	
80	    /**
81	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
82	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
83	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
84	     *
85	     * @param e Object referring to the thrown exception.
86	     * @param request {@link HttpServletRequest} object referring to the current request.
87	     * @param detail the human-readable detail message.
88	     * @param errors the names of the fields whose values conflicted.
89	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
90	     */
91	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
92	        HttpStatus status = HttpStatus.CONFLICT;
93	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
94	        problemDetail.setProperty("errors", errors);
95	        return ResponseEntity.status(status).body(problemDetail);
96	    }
97	
98	    /**
99	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
100	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
101	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
102	     * would catch it and report an authorization failure as a 500.
103	     *
104	     * @param e The {@link AccessDeniedException} to propagate
105	     * @throws AccessDeniedException always
106	     */
107	    @ExceptionHandler(AccessDeniedException.class)
108	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
109	        throw e;
110	    }
111	
112	    /**
113	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
114	     *
115	     * @param e The {@link Exception} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
118	     */
119	    @ExceptionHandler(Exception.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
122	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
123	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
125	        return ResponseEntity.status(status).body(detail);
126	    }
127	
128	    /**
129	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
130	     * method returns a 404 Not Found status if an entity does not exist.
131	     *
132	     * @param e The {@link DataIntegrityViolationException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
135	     */
136	    @ExceptionHandler(DataIntegrityViolationException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
139	        logger.warn("Data integrity violation at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getMessage());
143	        logger.debug("Data integrity violation stacktrace", e);
144	        HttpStatus status = HttpStatus.NOT_FOUND;
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles exception thrown by Bean Validation on controller methods parameters
151	     *
152	     * @param e The {@link MethodArgumentNotValidException} to be handled
153	     * @param request {@link HttpServletRequest} object referring to the current request.
154	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
155	     */
156	    @ExceptionHandler(MethodArgumentNotValidException.class)
157	    @ResponseBody
158	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
159	        HttpStatus status = HttpStatus.BAD_REQUEST;
160	        BindingErrorsResponse errors = new BindingErrorsResponse();
161	        BindingResult bindingResult = e.getBindingResult();
162	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
163	        if (bindingResult.hasErrors()) {
164	            errors.addAllErrors(bindingResult);
165	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
166	                .map(FieldError::getField)
167	                .distinct()
168	                .toList();
169	            detail.setProperty("errors", invalidFields);
170	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
171	                .map(fieldError -> {
172	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
173	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
174	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
175	                        fieldError.getField(),
176	                        defaultMessage,
177	                        rejectedValue);
178	                    return new ValidationMessageDto(message)
179	                        .putAdditionalProperty("field", fieldError.getField())
180	                        .putAdditionalProperty("rejectedValue", rejectedValue)
181	                        .putAdditionalProperty("defaultMessage", defaultMessage);
182	                })
183	                .toList();
184	            logger.debug("Validation error at {} {}: {}",
185	                request.getMethod(),
186	                request.getRequestURI(),
187	                bindingResult.getFieldErrors());
188	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
189	            return ResponseEntity.status(status).body(detail);
190	        }
191	        return ResponseEntity.status(status).body(detail);
192	    }
193	
194	    /**
195	     * Handles {@link InvalidOwnerFieldsException} raised when an owner has required fields that are
196	     * present but blank (whitespace-only). Returns a 400 Bad Request whose body carries an
197	     * {@code errors} array listing the name of each blank field, mirroring the shape produced for
198	     * Bean Validation failures.
199	     *
200	     * @param e The {@link InvalidOwnerFieldsException} to be handled
201	     * @param request {@link HttpServletRequest} object referring to the current request.
202	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
203	     */
204	    @ExceptionHandler(InvalidOwnerFieldsException.class)
205	    @ResponseBody
206	    public ResponseEntity<ProblemDetail> handleInvalidOwnerFieldsException(InvalidOwnerFieldsException e, HttpServletRequest request) {
207	        HttpStatus status = HttpStatus.BAD_REQUEST;
208	        logger.debug("Blank owner fields at {} {}: {}",
209	            request.getMethod(),
210	            request.getRequestURI(),
211	            e.getFields());
212	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
213	        detail.setProperty("errors", e.getFields());
214	        return ResponseEntity.status(status).body(detail);
215	    }
216	
217	    /**
218	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner submitted to the create
219	     * endpoint has a normalized telephone that is already used by another existing owner. Returns a
220	     * 409 Conflict.
221	     *
222	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
225	     */
226	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
229	        logger.debug("Duplicate owner telephone at {} {}: {}",
230	            request.getMethod(),
231	            request.getRequestURI(),
232	            e.getTelephone());
233	        return this.conflict(e, request, ERROR_DUPLICATE_TELEPHONE, List.of("telephone"));
234	    }
235	
236	    /**
237	     * Handles {@link DuplicateOwnerEmailException} raised when an owner submitted to the create
238	     * endpoint has a normalized (lower-cased) email that is already used by another existing owner.
239	     * Returns a 409 Conflict.
240	     *
241	     * @param e The {@link DuplicateOwnerEmailException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
244	     */
245	    @ExceptionHandler(DuplicateOwnerEmailException.class)
246	    @ResponseBody
247	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerEmailException(DuplicateOwnerEmailException e, HttpServletRequest request) {
248	        logger.debug("Duplicate owner email at {} {}: {}",
249	            request.getMethod(),
250	            request.getRequestURI(),
251	            e.getEmail());
252	        return this.conflict(e, request, ERROR_DUPLICATE_EMAIL, List.of("email"));
253	    }
254	
255	    /**
256	     * Handles {@link DuplicateOwnerHouseholdException} raised when an owner submitted to the create
257	     * endpoint shares a household with an existing owner (same last name and address) without opting
258	     * in via {@code sharesHousehold}. Returns a 409 Conflict.
259	     *
260	     * @param e The {@link DuplicateOwnerHouseholdException} to be handled
261	     * @param request {@link HttpServletRequest} object referring to the current request.
262	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
263	     */
264	    @ExceptionHandler(DuplicateOwnerHouseholdException.class)
265	    @ResponseBody
266	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerHouseholdException(DuplicateOwnerHouseholdException e, HttpServletRequest request) {
267	        logger.debug("Duplicate owner household at {} {}: {}, {}",
268	            request.getMethod(),
269	            request.getRequestURI(),
270	            e.getLastName(),
271	            e.getAddress());
272	        return this.conflict(e, request, ERROR_DUPLICATE_HOUSEHOLD, List.of("lastName", "address"));
273	    }
274	
275	    /**
276	     * Handles {@link OwnerCityAtCapacityException} raised when an owner submitted to the create
277	     * endpoint would be placed in a city that already contains the maximum number of owners (50 or
278	     * more). Returns a 409 Conflict.
279	     *
280	     * @param e The {@link OwnerCityAtCapacityException} to be handled
281	     * @param request {@link HttpServletRequest} object referring to the current request.
282	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
283	     */
284	    @ExceptionHandler(OwnerCityAtCapacityException.class)
285	    @ResponseBody
286	    public ResponseEntity<ProblemDetail> handleOwnerCityAtCapacityException(OwnerCityAtCapacityException e, HttpServletRequest request) {
287	        logger.debug("Owner city at capacity at {} {}: {}",
288	            request.getMethod(),
289	            request.getRequestURI(),
290	            e.getCity());
291	        return this.conflict(e, request, ERROR_CITY_AT_CAPACITY, List.of("city"));
292	    }
293	
294	    /**
295	     * Handles {@link DailyOwnerRegistrationLimitException} raised when an owner submitted to the
296	     * create endpoint would exceed the maximum number of owners that may be registered on a single
297	     * day (100 or more owners already carry today's {@code registrationDate}). Returns a
298	     * 429 Too Many Requests whose body carries an {@code errors} array naming the
299	     * {@code registrationDate} field, matching the shape produced for the other owner-creation error
300	     * responses.
301	     *
302	     * @param e The {@link DailyOwnerRegistrationLimitException} to be handled
303	     * @param request {@link HttpServletRequest} object referring to the current request.
304	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
305	     */
306	    @ExceptionHandler(DailyOwnerRegistrationLimitException.class)
307	    @ResponseBody
308	    public ResponseEntity<ProblemDetail> handleDailyOwnerRegistrationLimitException(DailyOwnerRegistrationLimitException e, HttpServletRequest request) {
309	        logger.debug("Daily owner registration limit reached at {} {}: {}",
310	            request.getMethod(),
311	            request.getRequestURI(),
312	            e.getDate());
313	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
314	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
315	        detail.setProperty("errors", List.of("registrationDate"));
316	        return ResponseEntity.status(status).body(detail);
317	    }
318	
319	}
